function AgencyLoginScreen({ agencies, password, setPassword, status, onLogin, onExternal, subspaceEntry }: any) {
  const cards = agencies.filter((agency: Agency) => ["paradise", "respawn", "horizon", "trident", "first-class-dan-james"].includes(agency.id)).sort((first: Agency, second: Agency) => ["paradise", "respawn", "horizon", "trident", "first-class-dan-james"].indexOf(first.id) - ["paradise", "respawn", "horizon", "trident", "first-class-dan-james"].indexOf(second.id));
  const [selected, setSelected] = useState(""); const [externalOpen, setExternalOpen] = useState(false); const [externalPassword, setExternalPassword] = useState("");
  const selectedAgency = cards.find((agency: Agency) => agency.id === selected);
  function chooseAgency(id: string) { setSelected(id); setExternalOpen(false); requestAnimationFrame(() => document.getElementById("agency-password")?.scrollIntoView({ behavior: "smooth", block: "center" })); }
  useEffect(() => { const heading = Array.from(document.querySelectorAll("h2")).find((element) => element.textContent?.includes("DAN / JAMES BATTLE SHEET")); const card = heading?.closest("section"); const button = heading?.closest("button"); if (!heading || !card || !button) return; const agencyGrid = card.previousElementSibling; agencyGrid?.before(card); card.style.cssText = "margin-top:40px;width:100%;overflow:hidden;border:1px solid rgba(253,224,71,.65);border-radius:24px;background:rgba(255,255,255,.025);padding:12px"; button.setAttribute("aria-label", "Open Dan and James First Class battle sheet"); button.style.cssText = "display:block;width:100%;padding:0;text-align:center;cursor:pointer;background:transparent;border:0"; button.innerHTML = '<img src="/agency-logos/first-class-dan-james-transparent.png" alt="First Class Dan and James" style="display:block;width:100%;max-width:760px;height:110px;margin:0 auto;object-fit:contain"/><span style="display:block;padding:4px 0 2px;color:#fef3c7;font:900 11px Arial;letter-spacing:.22em">ENTER BATTLE SHEET</span>'; }, []);
  useLayoutEffect(() => { if (externalOpen) void onExternal("BATTLE"); }, [externalOpen, onExternal]);
  return <main className="min-h-screen bg-[#050505] px-5 py-12 text-white"><div className="mx-auto max-w-5xl"><header className="text-center"><p className="text-xs font-black uppercase tracking-[.3em] text-yellow-200">ARRANGED BATTLES</p><h1 className="mt-3 font-[family-name:var(--font-norwester)] text-5xl uppercase">BATTLE <span className="text-yellow-300">NETWORK</span></h1><p className="mt-3 text-sm text-white/60">SELECT YOUR AGENCY TO OPEN ITS BATTLE SHEET.</p></header><section className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{cards.filter((agency: Agency) => agency.id !== "first-class-dan-james").map((agency: Agency) => <button key={agency.id} onClick={() => chooseAgency(agency.id)} className={`min-h-44 rounded-3xl border p-6 text-left transition ${selected === agency.id ? "bg-white/10 ring-2" : "bg-white/[.025] hover:bg-white/[.06]"}`} style={{ borderColor: selected === agency.id ? agency.accent : `${agency.accent}66`, ...(selected === agency.id ? { "--tw-ring-color": agency.accent } : {}) }}><div className="flex h-full flex-col justify-between"><AgencyMark agency={agency}/><div><p className="font-[family-name:var(--font-norwester)] text-2xl" style={{ color: agency.accent }}>{agency.name}</p><p className="mt-3 text-xs font-black uppercase text-white/55">ENTER BATTLE SHEET →</p></div></div></button>)}</section><section className="mt-5 rounded-3xl border border-yellow-300/30 bg-white/[.025] p-6"><button onClick={() => chooseAgency("first-class-dan-james")} className="text-left"><p className="text-xs font-black uppercase tracking-[.2em] text-yellow-200">FIRST CLASS</p><h2 className="mt-2 font-[family-name:var(--font-norwester)] text-2xl">DAN / JAMES BATTLE SHEET</h2></button></section>{selectedAgency ? <form id="agency-password" onSubmit={(event) => onLogin(event, selected)} className="mx-auto mt-5 max-w-xl rounded-3xl border bg-white/[.04] p-6" style={{ borderColor: selectedAgency.accent }}><p className="text-xs font-black uppercase" style={{ color: selectedAgency.accent }}>{selectedAgency.name}</p><label className="mt-4 block text-xs font-black uppercase text-white/60">AGENCY PASSWORD<input required autoFocus type="password" value={password} onChange={(event) => setPassword(event.target.value)} className="mt-2 w-full rounded-xl border border-white/15 bg-black p-4 text-white"/></label><button className="mt-4 w-full rounded-xl p-4 text-xs font-black uppercase text-black" style={{ background: selectedAgency.accent }}>ENTER BATTLE NETWORK</button></form> : null}<section className="mt-8 border-t border-white/10 pt-8"><button onClick={() => { setExternalOpen(!externalOpen); setSelected(""); }} className="w-full rounded-3xl border border-white/15 bg-white/[.025] p-6 text-left hover:bg-white/[.06]"><p className="text-xs font-black uppercase tracking-[.22em] text-sky-300">EXTERNAL AGENCIES</p><h2 className="mt-2 font-[family-name:var(--font-norwester)] text-3xl">AVAILABLE BATTLES</h2><p className="mt-2 text-sm text-white/60">VIEW OPEN BATTLES AND PAIR YOUR CREATOR.</p></button>{externalOpen ? <form onSubmit={(event) => { event.preventDefault(); void onExternal(externalPassword); }} className="mx-auto mt-4 max-w-xl rounded-3xl border border-sky-300/40 bg-sky-300/5 p-6"><label className="text-xs font-black uppercase text-sky-200">EXTERNAL AGENCY PASSWORD<input required autoFocus type="password" value={externalPassword} onChange={(event) => setExternalPassword(event.target.value)} className="mt-2 w-full rounded-xl border border-white/15 bg-black p-4 text-white"/></label><button className="mt-4 w-full rounded-xl bg-sky-300 p-4 text-xs font-black uppercase text-black">VIEW AVAILABLE BATTLES</button></form> : null}</section>{status && status !== "ENTER YOUR AGENCY PASSWORD." ? <p className="mt-5 text-center text-xs font-black uppercase text-red-300">{status}</p> : null}</div></main>;
}

function ExternalBattleScreen({ rows, agencies, week, setWeek, onExit, onClaim }: any) {
  const [claiming, setClaiming] = useState<Battle | null>(null); const [passwordAgency, setPasswordAgency] = useState<Agency | null>(null); const [agencyId, setAgencyId] = useState(() => typeof window === "undefined" ? "" : sessionStorage.getItem("battle-network-external-agency") || ""); const byId = (id: string) => agencies.find((agency: Agency) => agency.id === id); const partners = agencies.filter((agency: Agency) => agency.externalOnly); const activeAgency = byId(agencyId); const pinned = typeof window === "undefined" ? [] : (() => { try { const value = sessionStorage.getItem("battle-network-external-confirmed"); return value ? [JSON.parse(value) as Battle] : []; } catch { return []; } })(); const ordered = [...pinned, ...[...rows].sort((a: Battle, b: Battle) => DAYS.indexOf(a.day) - DAYS.indexOf(b.day) || a.requestedTime.localeCompare(b.requestedTime))];
  useEffect(() => { if (agencyId) return; const selectAgency = (event: MouseEvent) => { const button = (event.target as HTMLElement | null)?.closest("button"); const label = button?.textContent?.trim().toUpperCase(); const partner = partners.find((agency: Agency) => label?.includes(agency.name)); if (!button || !partner) return; event.preventDefault(); event.stopImmediatePropagation(); setPasswordAgency(partner); }; document.addEventListener("click", selectAgency, true); return () => document.removeEventListener("click", selectAgency, true); }, [agencyId, partners]);
  useEffect(() => { if (!passwordAgency) return; const overlay = document.createElement("div"); overlay.style.cssText = "position:fixed;inset:0;z-index:9999;display:grid;place-items:center;background:rgba(0,0,0,.82);padding:20px"; const card = document.createElement("form"); card.style.cssText = "width:min(420px,100%);border:1px solid #7dd3fc;border-radius:24px;background:#111;padding:28px;box-shadow:0 24px 80px rgba(0,0,0,.6);color:#fff"; card.innerHTML = `<p style=\"margin:0;color:#7dd3fc;font:900 11px Arial;letter-spacing:.18em\">EXTERNAL AGENCY ACCESS</p><h2 style=\"margin:12px 0 6px;font:900 28px Arial\">${passwordAgency.name}</h2><p style=\"margin:0 0 18px;color:#a3a3a3;font:13px Arial\">ENTER YOUR AGENCY PASSWORD TO VIEW AVAILABLE BATTLES.</p><input type=\"password\" autofocus placeholder=\"AGENCY PASSWORD\" style=\"box-sizing:border-box;width:100%;border:1px solid #444;border-radius:12px;background:#000;padding:14px;color:#fff;font-weight:700\"/><p data-error style=\"min-height:18px;margin:10px 0 0;color:#fca5a5;font:700 11px Arial\"></p><div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px\"><button type=\"button\" data-close style=\"border:1px solid #444;border-radius:12px;background:#171717;padding:13px;color:#fff;font-weight:900\">CLOSE</button><button style=\"border:0;border-radius:12px;background:#7dd3fc;padding:13px;color:#050505;font-weight:900\">ENTER AGENCY</button></div>`; overlay.append(card); document.body.append(overlay); const input = card.querySelector("input") as HTMLInputElement; const error = card.querySelector("[data-error]") as HTMLElement; const close = () => setPasswordAgency(null); card.querySelector("[data-close]")?.addEventListener("click", close); card.onsubmit = async (event) => { event.preventDefault(); const response = await fetch("/api/battle-network", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "external-select", agencyId: passwordAgency.id, password: input.value }) }); if (!response.ok) { error.textContent = "ACCESS DENIED. CHECK THE PASSWORD."; return; } sessionStorage.setItem("battle-network-external-agency", passwordAgency.id); setAgencyId(passwordAgency.id); close(); }; input.focus(); return () => overlay.remove(); }, [passwordAgency]);
  if (activeAgency) return <ExternalAgencyBattleBoard rows={rows} agency={activeAgency} agencies={agencies} week={week} setWeek={setWeek} onExit={onExit} onClaim={onClaim} />;
  if (!activeAgency) return <main className="min-h-screen bg-[#050505] px-5 py-12 text-white"><div className="mx-auto max-w-4xl"><div className="rounded-3xl border border-sky-300/30 bg-white/[.025] p-7"><p className="text-xs font-black uppercase tracking-[.22em] text-sky-300">EXTERNAL AGENCIES</p><h1 className="mt-3 font-[family-name:var(--font-norwester)] text-4xl">SELECT YOUR AGENCY</h1><p className="mt-3 max-w-2xl text-sm text-white/60">CHOOSE YOUR AGENCY BEFORE VIEWING BATTLES. ANY PAIRING WILL THEN USE YOUR AGENCY NAME AND LOGO.</p><div className="mt-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{partners.map((partner: Agency) => <button key={partner.id} onClick={() => { setAgencyId(partner.id); sessionStorage.setItem("battle-network-external-agency", partner.id); }} className="group min-h-44 rounded-2xl border bg-black/45 p-5 text-left transition hover:bg-white/[.07]" style={{ borderColor: `${partner.accent}99` }}><div className="flex h-full flex-col justify-between"><div className="flex h-20 items-center justify-center overflow-hidden">{partner.name.toLowerCase().includes("haus") || partner.name.toLowerCase().includes("house of influence") ? <span className="scale-150"><AgencyMark agency={partner}/></span> : <AgencyMark agency={partner}/>}</div><div><p className="font-[family-name:var(--font-norwester)] text-xl uppercase" style={{ color: partner.accent }}>{partner.name}</p><p className="mt-2 text-[10px] font-black uppercase tracking-[.16em] text-white/50 group-hover:text-white/80">ENTER AVAILABLE BATTLES →</p></div></div></button>)}</div>{!partners.length ? <p className="mt-6 text-sm text-red-300">NO EXTERNAL AGENCIES HAVE BEEN ADDED YET.</p> : null}<button onClick={onExit} className="mt-7 text-xs font-black uppercase text-white/60">LOG OUT</button></div></div></main>;
  return <main className="min-h-screen bg-[#050505] px-5 py-8 text-white"><div className="mx-auto max-w-6xl"><header className="flex items-center justify-between border-b border-white/10 pb-5"><div><p className="text-xs font-black uppercase tracking-[.22em] text-sky-300">EXTERNAL AGENCIES</p><h1 className="mt-2 font-[family-name:var(--font-norwester)] text-4xl">AVAILABLE BATTLES</h1></div><button onClick={onExit} className="rounded-lg border border-white/15 px-4 py-2 text-xs font-black uppercase">LOG OUT</button></header><div className="mt-5 flex items-center justify-between gap-4"><p className="max-w-2xl text-sm text-white/60">PAIR A CREATOR, THEN TAKE NOTE OF THE OPPONENT AND TIME. THE BATTLE WILL DISAPPEAR ONCE CONFIRMED.</p><label className="text-xs font-black uppercase text-white/55">WEEK OF <input type="date" value={week} onChange={(event) => setWeek(event.target.value)} className="ml-2 rounded-lg border border-white/15 bg-black p-2 text-white"/></label></div><div className="mt-6 space-y-3">{ordered.map((battle: Battle) => { const agency = byId(battle.agencyId); return <article key={battle.id} className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-4 rounded-2xl border border-l-[6px] border-white/10 border-l-red-500 bg-white/[.025] p-5"><div className="grid gap-3 sm:grid-cols-4"><Field label="AGENCY"><div className="flex items-center gap-2"><AgencyMark agency={agency}/><span className="text-xs font-black" style={{ color: agency?.accent }}>{agency?.name}</span></div></Field><Field label="USERNAME"><strong>@{battle.creatorUsername}</strong><TikTokLink username={battle.creatorUsername}/></Field><Field label="SIZE"><span className={`inline-flex rounded-full px-3 py-1 text-xs font-black ${SIZE_STYLE[battle.size]}`}>{battle.size}</span></Field><Field label="TIME"><strong>{displayTime(battle.requestedTime)}</strong><span className="text-xs text-white/55">{battle.day}</span></Field></div><button onClick={() => setClaiming(battle)} className="rounded-xl bg-sky-300 px-5 py-4 text-xs font-black uppercase text-black">PAIR CREATOR</button></article> })}{!ordered.length ? <p className="rounded-2xl border border-white/10 p-8 text-center text-sm text-white/50">NO AVAILABLE BATTLES THIS WEEK.</p> : null}</div></div>{claiming ? <ExternalClaimModal battle={claiming} onClose={() => setClaiming(null)} onClaim={async (username: string) => { if (await onClaim(claiming, username)) setClaiming(null); }} /> : null}</main>;
}

function ExternalClaimModal({ battle, onClose, onClaim }: any) {
  const [username, setUsername] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  async function confirm() {
    if (!username.trim()) { setError("ENTER YOUR CREATOR USERNAME."); return; }
    setSubmitting(true); setError("");
    const confirmed = await onClaim(username.trim());
    if (!confirmed) { setError("BATTLE HAS BEEN CLAIMED. REFRESH AND CHOOSE ANOTHER BATTLE."); setSubmitting(false); }
  }
  return <div className="fixed inset-0 z-40 grid place-items-center bg-black/85 p-4"><div className="w-full max-w-md rounded-3xl border border-sky-300/40 bg-[#111] p-6"><p className="text-xs font-black uppercase text-sky-300">PAIR CREATOR</p><h2 className="mt-2 font-[family-name:var(--font-norwester)] text-3xl">{battle.size} · {displayTime(battle.requestedTime)}</h2><p className="mt-3 text-sm text-white/60">YOU ARE PAIRING AGAINST {battle.creatorUsername}. PLEASE TAKE NOTE OF THE OPPONENT AND TIME BEFORE CONFIRMING.</p><input required autoFocus value={username} onChange={(event) => setUsername(event.target.value)} placeholder="YOUR CREATOR USERNAME" className="mt-5 w-full rounded-xl border border-white/15 bg-black p-4 font-bold text-white"/><div className="mt-3 rounded-xl border border-white/15 bg-black p-4 text-sm font-black">LOCKED TIME: {displayTime(battle.requestedTime)}</div>{error ? <p className="mt-3 text-xs font-black uppercase text-red-300">{error}</p> : null}<div className="mt-4 grid grid-cols-2 gap-3"><button type="button" onClick={onClose} disabled={submitting} className="rounded-xl border border-white/15 p-4 text-xs font-black uppercase">CLOSE</button><button type="button" onClick={() => void confirm()} disabled={submitting} className="rounded-xl bg-sky-300 p-4 text-xs font-black uppercase text-black disabled:opacity-50">{submitting ? "CONFIRMING…" : "CONFIRM OPPONENT"}</button></div></div></div>;
}

function ExternalAgencyBattleBoard({ rows, agency, agencies, week, setWeek, onExit, onClaim }: any) {
  const [claiming, setClaiming] = useState<Battle | null>(null);
  const [sizes, setSizes] = useState<string[]>([]);
  const [days, setDays] = useState<string[]>([]);
  const cancelled: Battle[] = [];
  useEffect(() => { const anchor = document.querySelector("details"); if (!anchor || !cancelled.length || document.getElementById("cancelled-battles")) return; const section = document.createElement("section"); section.id = "cancelled-battles"; section.className = "mt-4 rounded-2xl border border-amber-400/35 bg-amber-400/[.04] p-4"; section.innerHTML = `<p class="text-sm font-black uppercase tracking-[.14em] text-amber-300">CANCELLED BATTLES ADDED BACK TO AVAILABLE BATTLES (${cancelled.length})</p>`; cancelled.forEach((battle: Battle) => { const row = document.createElement("div"); row.className = "mt-3 flex items-center justify-between gap-3 rounded-xl border border-amber-300/20 bg-black/30 p-3 text-sm"; row.innerHTML = `<span>@${battle.creatorUsername} · ${battle.day} · ${displayTime(battle.requestedTime)} · ${battle.size}</span>`; const button = document.createElement("button"); button.textContent = "WITHDRAW REQUEST"; button.className = "rounded-lg border border-red-300/50 px-3 py-2 text-[10px] font-black text-red-200"; button.onclick = async () => { button.disabled = true; button.textContent = "WITHDRAWING..."; const response = await fetch("/api/battle-network", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "external-withdraw", battleId: battle.id }) }); if (response.ok) { row.remove(); if (!section.querySelector("div")) section.remove(); } else { button.disabled = false; button.textContent = "TRY AGAIN"; } }; row.append(button); section.append(row); }); anchor.insertAdjacentElement("afterend", section); return () => section.remove(); }, [cancelled, agency.id]);
  const byId = (id: string) => agencies.find((item: Agency) => item.id === id);
  const toggleFilter = (value: string, values: string[], setValues: (next: string[]) => void) => setValues(values.includes(value) ? values.filter((item) => item !== value) : [...values, value]);
  const available = rows.filter((battle: Battle) => !battle.opponentBattleId && battle.agencyId !== agency.id && (!sizes.length || sizes.includes(battle.size)) && (!days.length || days.includes(battle.day))).sort((a: Battle, b: Battle) => WEEK_DAYS.indexOf(a.day) - WEEK_DAYS.indexOf(b.day) || minutes(a.requestedTime) - minutes(b.requestedTime) || a.creatorUsername.localeCompare(b.creatorUsername));
  const claimed = rows.filter((battle: Battle) => battle.agencyId === agency.id && battle.opponentBattleId && !battle.cancelledAt && !claimExpired(battle)).sort((a: Battle, b: Battle) => DAYS.indexOf(a.day) - DAYS.indexOf(b.day) || a.actualTime.localeCompare(b.actualTime));
  useEffect(() => { const heading = Array.from(document.querySelectorAll("h2")).find((element) => element.textContent === "OPEN BATTLES"); if (!heading) return; const old = document.getElementById("external-battle-filters"); old?.remove(); const filters = document.createElement("div"); filters.id = "external-battle-filters"; filters.className = "mt-4 rounded-2xl border border-white/10 bg-white/[.025] p-4"; const addGroup = (label: string, values: string[], selected: string[], update: (next: string[]) => void) => { const title = document.createElement("p"); title.className = "text-[10px] font-black uppercase tracking-[.15em] text-white/50"; title.textContent = label; filters.append(title); const group = document.createElement("div"); group.className = "mt-3 flex flex-wrap gap-2"; values.forEach((value) => { const labelElement = document.createElement("label"); labelElement.className = "flex cursor-pointer items-center gap-2 rounded-lg border border-white/15 px-3 py-2 text-xs font-black"; const input = document.createElement("input"); input.type = "checkbox"; input.checked = selected.includes(value); input.onchange = () => update(input.checked ? [...selected, value] : selected.filter((item) => item !== value)); labelElement.append(input, document.createTextNode(value)); group.append(labelElement); }); filters.append(group); }; addGroup("FILTER BY SIZE", SIZES, sizes, setSizes); addGroup("FILTER BY DAY", WEEK_DAYS, days, setDays); heading.insertAdjacentElement("afterend", filters); return () => filters.remove(); }, [sizes, days]);
  return <main className="min-h-screen bg-[#050505] px-5 py-8 text-white"><div className="mx-auto max-w-6xl"><header className="flex flex-wrap items-center justify-between gap-4 border-b border-white/10 pb-5"><div className="flex items-center gap-3"><AgencyMark agency={agency}/><div><p className="text-xs font-black uppercase tracking-[.22em]" style={{ color: agency.accent }}>{agency.name}</p><h1 className="mt-1 font-[family-name:var(--font-norwester)] text-4xl">AVAILABLE BATTLES</h1></div></div><button onClick={onExit} className="rounded-lg border border-white/15 px-4 py-2 text-xs font-black uppercase">LOG OUT</button></header><div className="mt-5 flex flex-wrap items-center justify-between gap-4"><p className="max-w-2xl text-sm text-white/60">OPEN BATTLES REFRESH AUTOMATICALLY. ONCE YOU CLAIM ONE, IT IS LOCKED FOR EVERY OTHER AGENCY.</p><label className="text-xs font-black uppercase text-white/55">WEEK OF <input type="date" value={week} onChange={(event) => setWeek(event.target.value)} className="ml-2 rounded-lg border border-white/15 bg-black p-2 text-white" /></label></div><details open className="mt-6 rounded-2xl border border-emerald-400/35 bg-emerald-400/[.04] p-4"><summary className="cursor-pointer text-sm font-black uppercase tracking-[.14em] text-emerald-300">CLAIMED BATTLES ({claimed.length})</summary><div className="mt-4 space-y-3">{claimed.map((battle: Battle) => { const opponent = rows.find((item: Battle) => item.id === battle.opponentBattleId); const opponentAgency = opponent ? byId(opponent.agencyId) : undefined; return <article key={battle.id} className="grid gap-4 rounded-xl border border-l-[6px] border-emerald-400/40 border-l-emerald-400 bg-black/35 p-4 sm:grid-cols-[1fr_1fr_auto]"><div><p className="text-[10px] font-black uppercase tracking-[.15em] text-white/45">YOUR CREATOR</p><div className="mt-1 flex items-center gap-2"><strong>{battle.creatorUsername}</strong><UsernameCopyButton username={battle.creatorUsername}/></div><TikTokLink username={battle.creatorUsername}/></div><div><p className="text-[10px] font-black uppercase tracking-[.15em] text-white/45">OPPONENT</p><div className="mt-1 flex items-center gap-2"><strong>{opponent?.creatorUsername || "CONFIRMED"}</strong>{opponent?.creatorUsername ? <UsernameCopyButton username={opponent.creatorUsername}/> : null}</div><p className="mt-1 text-xs font-black text-emerald-300">{battle.day} · {displayTime(battle.actualTime)} · {battle.size}</p></div><div className="flex items-center justify-start sm:justify-end"><AgencyMark agency={opponentAgency}/></div></article>; })}{!claimed.length ? <p className="py-3 text-sm text-white/45">NO BATTLES CLAIMED YET.</p> : null}</div></details><section className="mt-6"><h2 className="font-[family-name:var(--font-norwester)] text-3xl">OPEN BATTLES</h2><div className="mt-4 space-y-3">{available.map((battle: Battle) => { const sourceAgency = byId(battle.agencyId); return <article key={battle.id} className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-4 rounded-2xl border border-l-[6px] border-white/10 border-l-red-500 bg-white/[.025] p-5"><div className="grid gap-3 sm:grid-cols-4"><Field label="AGENCY"><div className="flex items-center gap-2"><AgencyMark agency={sourceAgency}/><span className="text-xs font-black" style={{ color: sourceAgency?.accent }}>{sourceAgency?.name}</span></div></Field><Field label="USERNAME"><strong>{battle.creatorUsername}</strong><TikTokLink username={battle.creatorUsername}/></Field><Field label="SIZE"><span className={`inline-flex rounded-full px-3 py-1 text-xs font-black ${SIZE_STYLE[battle.size]}`}>{battle.size}</span></Field><Field label="TIME"><strong>{displayTime(battle.requestedTime)}</strong><span className="text-xs text-white/55">{battle.day}</span></Field></div><button onClick={() => setClaiming(battle)} className="rounded-xl bg-sky-300 px-5 py-4 text-xs font-black uppercase text-black">PAIR CREATOR</button></article>; })}{!available.length ? <p className="rounded-2xl border border-white/10 p-8 text-center text-sm text-white/50">NO OPEN BATTLES THIS WEEK.</p> : null}</div></section></div>{claiming ? <ExternalClaimModal battle={claiming} onClose={() => setClaiming(null)} onClaim={async (username: string) => { if (await onClaim(claiming, username)) setClaiming(null); }} /> : null}</main>;
}

