type Battle = { id: string; agencyId: string; weekStart: string; day: string; creatorUsername: string; manager: string; size: string; powerUps: "POWER-UPS ALLOWED" | "NPU"; requestedTime: string; actualTime: string; opponentBattleId?: string; createdAt: string; cancelledAt?: string; cancelledBy?: string };
